import sys
import re
from html.parser import HTMLParser


class JSFilter(HTMLParser):
    """
    An HTML parser that removes JavaScript while preserving the rest of the HTML exactly.
    """

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.result = []
        self.skip_script = 0  # nesting depth for script tags
        self.skip_tag_stack = []  # stack to track tags being skipped

    # Tags whose entire content (including children) should be removed
    DANGEROUS_TAGS = {'script'}

    # Event handler attributes pattern (on*)
    EVENT_HANDLER_RE = re.compile(r'^on', re.IGNORECASE)

    # javascript: URL pattern - handles whitespace, mixed case, HTML entities
    JS_URL_RE = re.compile(
        r'^\s*(?:j|&#(?:x4a|x6a|74|106);?)\s*(?:a|&#(?:x41|x61|65|97);?)\s*(?:v|&#(?:x56|x76|86|118);?)\s*(?:a|&#(?:x41|x61|65|97);?)\s*(?:s|&#(?:x53|x73|83|115);?)\s*(?:c|&#(?:x43|x63|67|99);?)\s*(?:r|&#(?:x52|x72|82|114);?)\s*(?:i|&#(?:x49|x69|73|105);?)\s*(?:p|&#(?:x50|x70|80|112);?)\s*(?:t|&#(?:x54|x74|84|116);?)\s*(?::|&#(?:x3a|58);?)\s*',
        re.IGNORECASE | re.DOTALL
    )

    # Simpler javascript: check for common cases
    JS_URL_SIMPLE_RE = re.compile(
        r'^\s*j\s*a\s*v\s*a\s*s\s*c\s*r\s*i\s*p\s*t\s*:',
        re.IGNORECASE
    )

    # VBScript URL pattern
    VBS_URL_RE = re.compile(r'^\s*vbscript\s*:', re.IGNORECASE)

    # Data URL with dangerous content
    DATA_URL_RE = re.compile(r'^\s*data\s*:\s*text/html', re.IGNORECASE)

    # URL-bearing attributes
    URL_ATTRS = {'href', 'src', 'action', 'formaction', 'xlink:href', 'data', 'poster',
                 'background', 'dynsrc', 'lowsrc', 'code', 'codebase'}

    def _is_dangerous_url(self, value):
        """Check if a URL value contains javascript: or other dangerous protocols."""
        # Decode HTML entities first for checking
        decoded = value
        # Remove null bytes and other control characters that might be used to bypass
        cleaned = re.sub(r'[\x00-\x08\x0b\x0c\x0e-\x1f]', '', decoded)
        if self.JS_URL_SIMPLE_RE.match(cleaned):
            return True
        if self.JS_URL_RE.match(cleaned):
            return True
        if self.VBS_URL_RE.match(cleaned):
            return True
        if self.DATA_URL_RE.match(cleaned):
            return True
        return False

    def _is_dangerous_attr(self, tag, attr_name, attr_value):
        """Check if an attribute is dangerous."""
        attr_lower = attr_name.lower()

        # Event handlers
        if self.EVENT_HANDLER_RE.match(attr_lower):
            return True

        # URL attributes with javascript:
        if attr_lower in self.URL_ATTRS and attr_value is not None:
            if self._is_dangerous_url(attr_value):
                return True

        # style attribute with expression() or javascript:
        if attr_lower == 'style' and attr_value is not None:
            val_lower = attr_value.lower()
            if 'expression(' in val_lower or 'javascript:' in val_lower:
                return True
            # url() with javascript
            url_match = re.search(r'url\s*\(', val_lower)
            if url_match and 'javascript:' in val_lower:
                return True

        return False

    def _reconstruct_attrs(self, tag, attrs, raw_tag_text):
        """
        Remove dangerous attributes from the raw tag text.
        We parse which attrs are dangerous, then surgically remove them from the raw text.
        """
        dangerous_attrs = set()
        for attr_name, attr_value in attrs:
            if self._is_dangerous_attr(tag, attr_name, attr_value):
                dangerous_attrs.add(attr_name.lower())

        if not dangerous_attrs:
            return raw_tag_text

        # Use regex to remove dangerous attributes from the raw tag text
        # This preserves formatting of non-dangerous attributes
        result = raw_tag_text
        for attr_name in dangerous_attrs:
            # Match the attribute with optional value, handling various quoting styles
            # Pattern: attr_name (= ("..."|'...'|[^\s>]*))?
            pattern = re.compile(
                r'\s+' + re.escape(attr_name) + r'(?:\s*=\s*(?:"[^"]*"|' + r"'[^']*'" + r'|[^\s>]*))?',
                re.IGNORECASE | re.DOTALL
            )
            result = pattern.sub('', result)

        return result

    def handle_starttag(self, tag, attrs):
        if tag.lower() in self.DANGEROUS_TAGS:
            self.skip_script += 1
            return

        if self.skip_script > 0:
            return

        # Get the raw tag text from source
        raw = self.get_starttag_text()
        if raw is None:
            return

        # Filter dangerous attributes
        filtered = self._reconstruct_attrs(tag, attrs, raw)
        self.result.append(filtered)

    def handle_endtag(self, tag):
        if tag.lower() in self.DANGEROUS_TAGS:
            if self.skip_script > 0:
                self.skip_script -= 1
            return

        if self.skip_script > 0:
            return

        self.result.append('</' + tag + '>')

    def handle_data(self, data):
        if self.skip_script > 0:
            return
        self.result.append(data)

    def handle_comment(self, data):
        if self.skip_script > 0:
            return
        # Check for conditional comments or JS in comments
        # Remove comments that contain javascript
        self.result.append('<!--' + data + '-->')

    def handle_decl(self, decl):
        if self.skip_script > 0:
            return
        self.result.append('<!' + decl + '>')

    def handle_pi(self, data):
        if self.skip_script > 0:
            return
        self.result.append('<?' + data + '>')

    def handle_entityref(self, name):
        if self.skip_script > 0:
            return
        self.result.append('&' + name + ';')

    def handle_charref(self, name):
        if self.skip_script > 0:
            return
        self.result.append('&#' + name + ';')

    def unknown_decl(self, data):
        if self.skip_script > 0:
            return
        self.result.append('<![' + data + ']>')

    def get_output(self):
        return ''.join(self.result)


def filter_html(html_content):
    """Remove JavaScript from HTML content."""
    parser = JSFilter()
    parser.feed(html_content)
    return parser.get_output()


def main():
    if len(sys.argv) < 2:
        print("Usage: python filter.py <html_file>", file=sys.stderr)
        sys.exit(1)

    filepath = sys.argv[1]

    with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
        content = f.read()

